import{_ as e,o,c as a,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const p=JSON.parse('{"title":"World Narrative Model for Highly Controllable Video Generation: A Paradigm Shift from Pixel Sampling to Physical World Orchestration","description":"","frontmatter":{"title":"World Narrative Model for Highly Controllable Video Generation: A Paradigm Shift from Pixel Sampling to Physical World Orchestration","arxiv":"2606.31946","date":"2026-06-30","authors":"Ye Chen, Xuanhong Chen, Yupeng Zhu, Liming Tan, Zhewen Wan, Yuxuan Xiong, Tielong Wang, Jinfan Liu, Wuze Zhang, Xiongzhen Zhang, Feifei Li, Xianglin Luo, Zhehan Zhao, Zhifan Zhang, Laisheng Kou, Zhujin Liang, Yugang Chen, Muchun Chen, Xu Miao, Yijing Zhang, Xiaojie Sheng, Qiang Hu, Jialiang Chen, Weimin Zhang, Wenjun Zhang, Bingbing Ni","categories":"cs.CV","topics":"智能体视频生成, 可控性, 4D 世界表示","outline":[2,2]},"headers":[],"relativePath":"papers/2606.31946.md","filePath":"papers/2606.31946.md","lastUpdated":null}'),r={name:"papers/2606.31946.md"};function i(s,t,l,g,u,h){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="world-narrative-model-for-highly-controllable-video-generation-a-paradigm-shift-from-pixel-sampling-to-physical-world-orchestration" tabindex="-1">World Narrative Model for Highly Controllable Video Generation: A Paradigm Shift from Pixel Sampling to Physical World Orchestration <a class="header-anchor" href="#world-narrative-model-for-highly-controllable-video-generation-a-paradigm-shift-from-pixel-sampling-to-physical-world-orchestration" aria-label="Permalink to &quot;World Narrative Model for Highly Controllable Video Generation: A Paradigm Shift from Pixel Sampling to Physical World Orchestration&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2606.31946" target="_blank" rel="noreferrer">2606.31946</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-06-30</td></tr><tr><td><strong>作者</strong></td><td>Ye Chen, Xuanhong Chen, Yupeng Zhu, Liming Tan, Zhewen Wan, Yuxuan Xiong, Tielong Wang, Jinfan Liu, Wuze Zhang, Xiongzhen Zhang, Feifei Li, Xianglin Luo, Zhehan Zhao, Zhifan Zhang, Laisheng Kou, Zhujin Liang, Yugang Chen, Muchun Chen, Xu Miao, Yijing Zhang, Xiaojie Sheng, Qiang Hu, Jialiang Chen, Weimin Zhang, Wenjun Zhang, Bingbing Ni</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用一组 agent 先把文本搭成可编辑的 3D+T 白模世界（场景图、骨骼动作、相机路径、灯光参数），再把白模渲染帧当作控制条件喂给冻结的视频基模，让基模退化为&quot;神经着色器&quot;。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文要解决的不是画质问题，而是<strong>可控性</strong>问题。作者的判断很直接：Sora、Kling、Seedance、Wan 这些模型画质已到 1080p 至 4K，但对专业内容生产而言&quot;实际不可用&quot;。不可用体现为三条：同一 prompt 每次结果不同，无法锁定；用户无法直接指定关节角、物体位姿、灯位、精确相机轨迹；想改一个物体（比如抬高角色手臂）常常引发全局漂移，背景纹理变了、其他物体形变了、光照也变了。</p><p>重要性由一个产业数字支撑：论文称头部短剧制作方的数据显示，平均需要 20–50 次生成才能得到一个可用镜头，对需要精确调度的高端内容这个数字可超过每镜 100 次。由此产生一个悖论 —— 生成废片消耗的 token 成本常常超过最终视频的价值。导演的角色被降格为一个跟随机黑箱搏斗的 prompt engineer。</p><p>作者把真正的可控性拆成四个正交维度：Precision（说&quot;右肘弯曲 15 度&quot;就必须精确是 15 度，需要定量而非定性的控制通道）、Decoupling（改一个属性不波及其他属性与实体）、Consistency（同样参数每次产出相同结果，确定性是专业流程的前提）、Spatio-temporal Completeness（能在任意时空点施加控制，只给首尾帧不够）。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文对现有控制手段做了逐条否定，而且否定的理由都指向同一个结构性缺陷。Text prompt 直观但稀疏，描述不了精确的 3D 几何、材质属性与运动曲线。参考图/锚点图给了视觉约束，但中间运动完全不受控，时间上极度稀疏。运动轨迹与 kinematics 给了显式的关节运动路径，却管不了物体身份、光照与关节铰接。条件注入（semantic mask、depth、edge、pose）只在<strong>像素层</strong>工作，暴露不出&quot;色温&quot;&quot;肘关节角度&quot;这类高层物理语义。</p><p>更根本的诊断在于架构本身。主流视频基模是建立在深层 transformer 上的高维条件采样器，把每帧的像素分布当作一个极高维空间中的概率密度函数，扩散过程进一步引入随机迭代去噪，输出本质是这个概率空间里的随机游走。三个后果：一是绕过了 4D 物理世界，学到的是统计相关而非因果物理规则，&quot;看起来对&quot;但&quot;动起来错&quot;；二是稀疏指令到稠密输出的维度极端错配，这个数学上欠定的映射逼着模型幻觉出绝大多数细节；三是没有物理实体概念，整帧作为一个纠缠的像素分布生成，不分割也不跟踪个体，于是无法只编辑一个实例。</p><p>与具身智能的 world model（JEPA、Marble、WorldGen、Cosmos）的区别被单独讨论：那类模型输出的是动作、规划或隐特征，不为人类阅读设计，评价标准是任务成功率；而媒体世界模型输出的是可视化、可编辑的物理参数，评价标准是控制精度、编辑效率与用户满意度。作者还给出一个可行性论证 —— 媒体场景容忍物理近似（角色可以跳得比现实高、影子可以风格化），且数据可从海量公开影视素材自动标注获得，不依赖稀缺的机器人交互数据。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从产业侧的失败模式出发：每镜 20–100 次抽卡。为什么抽卡？因为用户的每次修改意图无法定向地作用到输出上，只能整体重采样。为什么无法定向？因为可修改的对象（文本）与被修改的对象（像素）之间没有中间表示，所有物理属性纠缠在黑箱 latent 里。</p><p>那么就需要一个中间层。这个中间层要满足什么？把上面四个可控性维度翻译过来就是五条能力：显式 3D 实体表示、解耦的控制节点、可编辑可视化、时序一致、（可选的）物理合理。这五条同时指向唯一的一个答案 —— 一个带显式实体的 3D+T 世界表示。</p><p>接下来是关键的工程判断：不重训基模。既然基模已经把&quot;从结构条件到高质量像素&quot;这件事做得足够好（video2video 条件化已是 Seedance 2.0 这类系统的标配接口），那就让它保持冻结，只负责着色。控制权全部上移到中间层。而中间层不必是一个新的大模型 —— 现成的 CV/CG 工具（3D 重建、深度估计、分割跟踪、Blender）已经足够，把它们编排成 agent workflow 即可，agent 之间交换结构化物理参数而不是像素。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>把&quot;渲染什么&quot;和&quot;怎么渲染&quot;彻底拆开。前者是一个低维、结构化、完全可编辑的物理叙事（场景图、6-DoF 摆放、骨骼动作、相机路径、灯光参数），它是<strong>结构确定的</strong> —— 同样输入产生同样蓝图；后者交给冻结的视频基模，它只做像素着色。指挥家读谱并指挥，乐队负责发声；两者都做不到的事，合起来能做到。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以&quot;古装人物在山间亭中抚琴，镜头从远景缓慢推到手部特写&quot;为例，四个 agent 依次工作：</p><ul><li><strong>Scene Layout Agent</strong>。generator agent 是一个被硬 prompt 规则约束的 LLM（每个可见网格必须有材质、物体必须注册 AABB、主体结构不得跳过），把语义解析出的 scene recipe 编译成可执行的 Blender Python 脚本，程序化地建出亭子、山体、植被。supervisor agent 做静态与动态双重校验：脚本语法、执行日志、运行异常、AABB 边界、用 Blender BVH 树做物体间碰撞检测、材质完整性、GLB 导出可行性。若有参考图/视频，它还调用 SAM3D、VGGT、VGGT-Omega、Depth Anything 3 估计相机参数与粗几何，从估计出的机位重渲当前场景，比较的<strong>不是 RGB 像素</strong>而是深度一致性、轮廓对齐、相对位置误差、物间距离偏差，把误差编成结构化报告回传（例如&quot;把桌子左移 0.2 米&quot;&quot;椅子缩小 5%&quot;）。循环直到约束满足或达到迭代上限。</li><li><strong>Asset Generation Agent</strong>。先由视觉语言 agent 把请求解析成 scene graph，节点是待生成物体（携带类别、材质、目标 6-DoF 位姿），边编码支撑、邻接、包含、朝向、尺度比与功能关系。然后走 retrieval-augmented 路线：先在约 65 万件预归一化 3D 资产库里做多阶段排序（语义召回、参考图与多视角缩略图的视觉相似、按包围盒比例与支撑面类型做几何重排）；若最高分低于阈值则切到生成分支，用一个 3.25B 参数、octree latent 表示的 3D 物体扩散模型，论文称在可比质量下比 Trellis 2.0 快约 40%。最后 placement agent 算初始 6-DoF 变换并做碰撞、支撑对齐、穿模检查，必要时用可微渲染器匹配参考轮廓。</li><li><strong>Motion Planning Agent</strong>。动作生成用 RVQ-VAE 把运动序列压成关节级离散 token（用 joint padding 与 masking 处理不同骨架规模），再用双层 transformer 由粗到细预测被 mask 的 token：base transformer 接收编码了关节类型、连通性、关节间距的骨架前缀，用余弦调度的 mask 比例学全局节奏，residual transformer 补高频细节（尾巴摆动、耳朵抖动）。文本编码器用 SigLIP2，骨架拓扑用 GNN 编码。模型 1.61 亿参数，在超过 4 万条动作片段的动物 4D 数据集上训练，覆盖四足、鸟类、鱼类，论文称是首个支持跨物种自由文本动作生成的模型。轨迹规划则是 Codex 生成 Blender 脚本 → 预渲染 → VLM 当 supervisor 检查穿模、悬空、转向不自然、穿墙 → 输出结构化错误报告（&quot;第 45 帧左脚与椅腿相交&quot;）并自动改写轨迹参数的闭环。</li><li><strong>Camera &amp; Lighting Agent</strong>。LLM 解析故事线识别关键时刻、所需景别与情绪基调，查一个预编译的 cinematography skill library 把叙事线索映射为参数化相机行为（&quot;戏剧性揭示&quot;→ 缓慢推近加轻微俯仰），再结合场景几何与角色位置优化轨迹以避遮挡、保持构图。灯光 agent 从 curated preset 库取主/辅/背光比、色温、阴影柔度，把虚拟光源放到物理合理的位置，可选地用可微渲染器对齐参考图。</li></ul><p>产物是一个白模世界。实验中它被渲成一串<strong>无真实纹理</strong>的白模帧，直接通过与 Seedance 2.0 内置 video2video 相同的接口喂给基模。上层还有一个人机协同平台：Workflow Canvas（生产流程的可视流图）、Entity Node Graph（实体与属性构成的图，边编码物理依赖，改一处自动传播）、Narrative Timeline（多轨时间线，任意属性可打关键帧插值），以及场景/资产、动作轨迹、摄影、灯光四块导演控制面板。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>测试集怎么建？</strong> 按场景类型（室内外）、运动模式（单人与多人交互）、相机运动（推、摇、跟、升降、弧形、环绕等）三重多样性构建，动作取自 Mixamo、InterHuman、InterX，补充自建场景图与分镜标注，并引入专业影片参考。最终约 3,000 个样本，覆盖 100 个代表性场景、超过 20,000 种动作模式、16 类相机操作。</p><p><strong>和什么比？</strong> 两条 baseline：text-only（新手模式，代表 Sora/Kling/Seedance 的原生用法）与 omni-reference（专业模式，文本 + 参考图 + 参考视频 + 显式的相机/轨迹描述，代表现有工具的能力上限）。平台覆盖 Seedance 2.0、Kling 2.6、Sora 2、Wan 2.6。关键设定是<strong>不训练任何 adapter</strong>，直接把白模帧作为控制输入，作者明确说这是为了隔离&quot;物理参数级控制范式&quot;本身的收益而非微调红利。</p><p><strong>结论一：范式本身有效。</strong> 用专业评委的成对 GSB（Good/Same/Bad）多数投票，WNM 对 text-only 的总体 GSB 为 2.75（73.3% 的对比中不劣于对方），对 omni-reference 为 2.02（66.9%）。分维度看，相机控制优势最大（3.33 / 2.35），场景控制次之（3.21 / 2.23），动作与轨迹控制最小（2.64 / 2.02）。一个值得注意的交叉对比是&quot;WNM + 新手 vs. 专业 baseline&quot;仍有 1.72，说明白模控制在一定程度上补偿了用户的经验差距。</p><p><strong>结论二：抽卡次数显著下降。</strong> 用户研究里新手每镜尝试从 18.6 降到 5.1（−72.6%），总创作时间从 74.2 分钟降到 29.8 分钟（−59.8%）；专业用户从 9.4 降到 3.2（−66.0%），时间 46.7 → 24.1 分钟（−48.4%）。主观 Likert 评分中提升最大的一项是控制准确性（新手 +1.9，专业 +1.2），与&quot;直接指定优于间接试探&quot;的论点一致。作者对专业用户时间节省相对较小给出的解释是：专业用户的时间有相当比例花在构图、节奏、风格这类高层创作决策上，工具加速的是意图的执行而非思考本身。</p><p>需要指出，论文在实验开篇提出的第三个问题是各 agentic 模块是否各自有实质贡献，但在抓取到的正文中没有看到与之对应的模块级 ablation 结果，定量证据只有 GSB 与用户研究两块。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：视频生成的可控性危机源于架构 —— 基模把整帧当作纠缠的像素分布采样，没有实体、没有物理参数、没有确定性。WNM 主张把&quot;渲染什么&quot;与&quot;怎么渲染&quot;拆开，前者交给一组 agent 构建的可编辑 3D+T 白模世界，后者交给冻结的基模当神经着色器。四个 agent 分别负责场景布局、资产生成与摆放、动作与轨迹、摄影与灯光，每个都是&quot;生成—校验—修复&quot;的闭环而非一次性猜测。不训练任何 adapter，仅用白模渲染帧作为 video2video 条件，就在专业评委的 GSB 上对最强的 omni-reference baseline 取得 2.02。用户研究显示每镜尝试次数下降约三分之二，这是这套范式最实在的产业价值。</p><p><strong>3 句话版</strong>：把控制权从 prompt 上移到一个显式的 3D+T 世界表示。基模冻结不动，只负责把白模着色成像素。抽卡从每镜 18.6 次降到 5.1 次。</p><p><strong>1 句话版</strong>：让视频基模退化为渲染器，把导演权还给一个可编辑的物理世界。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>冻结的视频基模会忠实执行白模帧给出的物理规格</strong>。整个论证链条建立在&quot;控制器是结构确定的&quot;之上，但最终交付给用户的是像素，而像素由一个随机采样的扩散模型产生。控制器再确定，只要渲染器在着色时&quot;自作主张&quot;地偏移了关节角度、改变了相机位置或重新解释了空间关系，Precision 与 Consistency 这两个维度就在最后一步失守。</p><p>论文对此的证据是间接的：GSB 由人类专家判断&quot;哪个更可控&quot;，用户研究记录尝试次数。这两类证据都无法回答&quot;指定 15 度是否真的得到 15 度&quot;。更能说明问题的是论文自己在标准化章节提出的诉求 —— 呼吁社区建立包含平均关节角误差、相机路径偏差、光照一致性分数、解耦分数（衡量编辑一个属性对其他属性的影响）的可控性 benchmark。提出这些指标恰恰意味着当前论文没有用它们来测量自己。</p><p>还有一个更隐蔽的问题：论文明确说白模帧&quot;不含真实纹理&quot;，是粗糙的显式代理。粗糙代理与最终像素之间存在一个巨大的补全空间，而这个空间正是基模自由发挥的地方。可以推断，控制精度会随着规格的精细程度而衰减 —— 场景布局这类粗粒度约束（GSB 3.21）比动作轨迹这类细粒度约束（2.64）表现更好，这个排序与该推断一致，但论文没有把它作为一个显式的假设来检验。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不复现四个 agent，只测量&quot;白模条件→最终像素&quot;这一段的控制保真度，因为整篇论文的确定性主张全押在这里。</p><p>用 Blender 手工搭 20 个极简白模场景，每个场景的相机路径与角色关节角都是<strong>程序化生成、数值已知</strong>的（例如相机沿指定 B 样条移动、右肘角度从 15 度线性变到 60 度）。渲染成无纹理白模帧，通过任一可访问的 video2video 接口驱动生成最终视频。然后反向测量：用 VGGT 或 COLMAP 从生成视频估计相机轨迹，用姿态估计器提取关节角，与规格值逐帧比对，报告相机路径偏差与平均关节角误差。同一白模用 5 个不同随机种子各跑一次，统计这两个误差的方差。</p><p>支持论文的结果是：误差均值小且种子间方差很小，说明基模确实在做&quot;着色&quot;而非&quot;再创作&quot;。反驳的结果是：误差随规格精细度显著上升，或种子间方差与文本条件下相当 —— 那说明确定性只存在于蓝图层，最终像素仍是抽卡，宣称的可控性有一段是名义上的。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>替代解释攻击：<strong>用户尝试次数的下降可能主要来自评价对象的转移，而非最终视频质量的提升</strong>。WNM 的用户在白模阶段就能看到并调整场景、动作、相机，很多轮迭代被转移到了这个廉价的预览环节；论文记录的&quot;每镜生成尝试次数&quot;只统计调用基模的次数，白模阶段的编辑轮次并不计入。若把&quot;从开始到接受的总创作时间&quot;作为唯一口径，新手仍有 −59.8% 的收益，这一点比尝试次数更有说服力；但对专业用户 −48.4% 的时间节省中，有多少来自白模编辑的效率、多少来自基模调用的减少，论文没有拆分。</p><p>更硬的攻击是<strong>确定性反例</strong>：固定同一份白模世界，用不同随机种子调用基模多次，把结果并排展示给专业评委，问&quot;这些输出在导演关心的维度上是否一致&quot;。论文把 Consistency 定义为&quot;给定相同控制参数必须每次产生相同结果&quot;，并把它列为专业流程的前提。由于渲染器是冻结的扩散模型且未做任何确定性化处理，这个测试很可能显示出可见的差异。若差异显著，论文关于四个可控性维度的表 I 自评（WNM 在 Deterministic Output 一栏被标为支持）就需要修正为&quot;结构确定、像素不确定&quot;。</p><p>另一类可预测失败被论文自己在 Limitations 里承认了：动作/轨迹生成与物体摆放是<strong>分开处理</strong>的，没有显式建模人—物交互。角色端起杯子、推动椅子这类动作需要角色铰接与物体 6-DoF 轨迹的协同生成，当前版本不支持。因此任何以&quot;接触&quot;为核心的镜头（递东西、开门、搬运）都是该系统的结构性盲区，而这恰恰是叙事影视里最常见的动作类别之一。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：控制器与渲染器之间是<strong>单向</strong>的。白模一旦渲成像素，就没有任何机制检查像素是否真的执行了规格，也没有任何信号能回流去修正。前四个 agent 内部都是&quot;生成—校验—修复&quot;的闭环，唯独最后这一步、也是唯一面向最终交付物的一步，是开环的。</p><p><strong>新 framing</strong>：把控制器—渲染器的关系从&quot;编译&quot;改成&quot;<strong>带验证的编译</strong>&quot;，即引入一个 inverse rendering 的验证回路。生成视频后，用 3D 重建与姿态估计把像素<strong>反解</strong>回一组物理参数，与原始白模规格逐项比对，得到一个可量化的 control fidelity 残差；这个残差既可以直接反馈给用户（哪一帧、哪个关节、偏了多少），也可以作为优化信号去调整白模、重选种子，或训练轻量 adapter。</p><p><strong>可借鉴的相邻领域工具</strong>：一是计算机图形学里的 analysis-by-synthesis 与可微渲染 —— 论文已经在 asset placement 和灯光对齐里局部用到可微渲染器，把同一思路提升到系统的最外层是自然的延伸。二是形式化验证里的 refinement checking：把白模世界当作 specification，把生成视频当作 implementation，控制保真度就是精化关系是否成立的度量。这个类比给出一个有用的设计原则 —— 规格应当分层，粗粒度约束（物体不穿墙）必须硬性成立，细粒度约束（肘部 15 度）允许带容差，这恰好对应论文自己提出的 L0–L4 分级表示。</p><p><strong>第一个实验</strong>：先不做闭环，只把测量工具建起来。在论文的 3,000 样本测试集上，对每个样本自动反解相机轨迹与主要角色的关节角，计算与白模规格的偏差，得到一张&quot;控制保真度 vs. 规格粒度&quot;的曲线。如果曲线在细粒度端明显衰减，闭环校正的价值就被定量地确立了，同时这张曲线本身就是论文所呼吁的可控性 benchmark 的第一个可用实例；如果曲线平坦且误差很小，说明冻结基模已经足够听话，研究重心应转向 agent 侧的规格生成精度而非渲染侧的验证。</p>',50)])])}const q=e(r,[["render",i]]);export{p as __pageData,q as default};
